$path = "C:\Users\CJErno\Desktop\FaceAtt\index.html"
$s = Get-Content $path -Raw
$old = "   #prompt { position:absolute; left:10px; right:10px; top:10px; padding:12px; border-radius:10px; background:rgba(59,130,246,.92); text-align:center; font-size:20px; font-weight:700; }`r`n   [hidden] { display:none !important; }"
$neu = "   #prompt { position:absolute; left:10px; right:10px; top:10px; padding:12px; border-radius:10px; background:rgba(59,130,246,.92); text-align:center; font-size:20px; font-weight:700; }`r`n`r`n   /* Modal */`r`n   .modal-overlay { position:fixed; inset:0; background:rgba(0,0,0,0.7); backdrop-filter:blur(4px); display:flex; align-items:center; justify-content:center; z-index:1000; animation:fadeIn 0.3s ease; }`r`n   .modal { background:var(--card); border-radius:16px; max-width:400px; width:90%; padding:32px 24px; text-align:center; box-shadow:0 20px 60px rgba(0,0,0,0.5); border:2px solid var(--border); animation:scaleIn 0.3s ease; position:relative; overflow:hidden; }`r`n   .modal.success { border-color:var(--ok); }`r`n   .modal.warning { border-color:var(--warn); }`r`n   .modal-icon { font-size:64px; margin-bottom:16px; display:block; animation:bounce 0.6s ease; }`r`n   .modal-title { font-size:24px; font-weight:700; margin:0 0 12px; }`r`n   .modal.success .modal-title { color:var(--ok); }`r`n   .modal.warning .modal-title { color:var(--warn); }`r`n   .modal-message { font-size:16px; color:var(--text); margin:0 0 24px; line-height:1.5; }`r`n   .modal-btn { padding:12px 32px; border:0; border-radius:10px; background:var(--accent); color:#fff; font-size:16px; font-weight:600; cursor:pointer; transition:transform 0.2s; }`r`n   .modal-btn:hover { transform:scale(1.05); }`r`n   .modal.success .modal-btn { background:var(--ok); }`r`n   .modal.warning .modal-btn { background:var(--warn); color:#000; }`r`n   @keyframes fadeIn { from { opacity:0; } to { opacity:1; } }`r`n   @keyframes scaleIn { from { transform:scale(0.8); opacity:0; } to { transform:scale(1); opacity:1; } }`r`n   @keyframes bounce { 0%, 100% { transform:translateY(0); } 50% { transform:translateY(-10px); } }`r`n   #confetti-canvas { position:fixed; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:1001; }`r`n   [hidden] { display:none !important; }"
if ($s.Contains($old)) {
    $s2 = $s.Replace($old, $neu)
    Set-Content $path $s2
    Write-Host "ok"
} else {
    Write-Host "no"
}
